sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // 1. Get the raw payload data and normalize it to a string
    var rawPayloadString = "";
    var requestBody = request.body.data;

    if (typeof requestBody === 'string') {
        rawPayloadString = requestBody;
    } else if (typeof requestBody === 'object') {
        // If ServiceNow already parsed it into an object, convert it back to a string for storage
        rawPayloadString = JSON.stringify(requestBody);
    }

    try {
        // 2. Insert the raw string into the DER payload table
        var payloadGr = new GlideRecord('x_704340_der_der_payload');
        payloadGr.initialize();

        // NOTE: Verify if your column name is 'payload' or 'u_payload'
        payloadGr.setValue('payload', rawPayloadString); 
        var payloadSysId = payloadGr.insert();

        if (!payloadSysId) {
            return new sn_ws_err.InternalError("Failed to log payload to the DER table.");
        }

        // 3. Send a lightweight success response back immediately to prevent timeouts
        var responseBody = {
            "status": "Success",
            "message": "Payload captured successfully.",
            "payload_sys_id": payloadSysId
        };

        response.setBody(responseBody);
        response.setStatus(200); // 200 OK

    } catch (ex) {
        return new sn_ws_err.InternalError("An error occurred while saving the payload: " + ex.message);
    }

})(request, response);
